def transform(grid):
    if not grid:
        return grid

    from collections import Counter

    # Count color frequencies
    counts = Counter(val for row in grid for val in row)

    # Determine the target color to change
    # In demonstrations, 0 was the target (background).
    # Here 0 is absent. Heuristic suggests picking the most frequent color
    # (as 0 is usually the most frequent background color).
    # Previous submission targeted the minimum color count (6) and failed,
    # suggesting 8 (the most frequent) is the correct target.
    target = 0
    if 0 in counts:
        target = 0
    elif counts:
        target = max(counts, key=counts.get)

    visited = set()
    # We modify the grid in-place or return a copy
    result_grid = [list(row) for row in grid]
    rows, cols = len(grid), len(grid[0])

    for r in range(rows):
        for c in range(cols):
            if result_grid[r][c] == target and (r, c) not in visited:
                component = []
                stack = [(r, c)]
                visited.add((r, c))

                while stack:
                    cr, cc = stack.pop()
                    component.append((cr, cc))

                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if result_grid[nr][nc] == target and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                stack.append((nr, nc))

                # Check if the component touches the boundary
                touches_boundary = any(
                    nr == 0 or nr == rows - 1 or nc == 0 or nc == cols - 1
                    for nr, nc in component
                )

                # If enclosed, replace with 4
                if not touches_boundary:
                    for nr, nc in component:
                        result_grid[nr][nc] = 4

    return result_grid
